"""SQLAlchemy database models for DefenSync."""

from __future__ import annotations

import uuid
from datetime import datetime, timezone

from sqlalchemy import BigInteger, Boolean, Column, DateTime, Float, Index, Integer, String, Text, UniqueConstraint
from sqlalchemy.orm import declarative_base

Base = declarative_base()

DATA_SCOPE_PRIVATE = "PRIVATE"
DATA_SCOPE_GLOBAL = "GLOBAL"
GLOBAL_DATA_ORIGINS = frozenset({"PUBLIC_DATASET", "SYNTHETIC", "SYNTHETIC_CLOUD_DEMO"})
# Private, account-scoped records generated by DefenSync for a presentation; never ML input.
PRESENTATION_DATA_ORIGIN = "PRESENTATION_SIMULATED"


class Account(Base):
    """Customer/tenant account that owns users, servers, and private LIVE_LINUX telemetry."""
    __tablename__ = "accounts"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    name = Column(String(80), unique=True, nullable=False, index=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class User(Base):
    """Database model for registered system accounts."""
    __tablename__ = "users"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    name = Column(String(50), unique=True, nullable=True, index=True)
    username = Column(String(50), unique=True, nullable=False, index=True)
    email = Column(String(100), unique=True, nullable=False, index=True)
    password_hash = Column(String(255), nullable=True)
    hashed_password = Column(String(255), nullable=False)
    role = Column(String(20), nullable=False, default="ANALYST")
    account_id = Column(String(36), nullable=True, index=True)
    # Per-user max active trusted browser devices (PENDING + VERIFIED). Independent of other users.
    device_limit = Column(Integer, nullable=False, default=3)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class TrustedDevice(Base):
    """Browser device enrolled after MFA via possession of a device-held private key.

    Private keys never leave the client. Public key + metadata only are stored here.
    Distinct from JWT login sessions and from monitored Linux servers.
    """
    __tablename__ = "trusted_devices"
    __table_args__ = (
        UniqueConstraint("user_id", "public_key_thumbprint", name="uq_trusted_device_user_thumbprint"),
        Index("ix_trusted_devices_user_status", "user_id", "status"),
    )

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    user_id = Column(String(36), nullable=False, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    display_name = Column(String(120), nullable=False, default="Trusted device")
    public_key_jwk = Column(Text, nullable=False)
    public_key_thumbprint = Column(String(64), nullable=False, index=True)
    key_algorithm = Column(String(20), nullable=False, default="ES256")
    # PENDING until challenge proof succeeds; VERIFIED is trusted; REVOKED never auto-reactivates.
    status = Column(String(20), nullable=False, default="PENDING", index=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    enrolled_at = Column(DateTime, nullable=True)
    last_seen_at = Column(DateTime, nullable=True)
    revoked_at = Column(DateTime, nullable=True)
    enroll_source_ip = Column(String(45), nullable=True)
    enroll_user_agent = Column(String(512), nullable=True)
    last_source_ip = Column(String(45), nullable=True)
    last_user_agent = Column(String(512), nullable=True)


class DeviceChallenge(Base):
    """One-time, expiring challenge bound to a device enrollment or return proof. Replay-invalid after use."""
    __tablename__ = "device_challenges"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    user_id = Column(String(36), nullable=False, index=True)
    device_id = Column(String(36), nullable=True, index=True)
    purpose = Column(String(20), nullable=False, index=True)  # ENROLL | VERIFY
    nonce_hash = Column(String(64), nullable=False)
    expires_at = Column(DateTime, nullable=False, index=True)
    used_at = Column(DateTime, nullable=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class Server(Base):
    """Linux server registered for SSH log collection and behavioral monitoring."""
    __tablename__ = "servers"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    server_name = Column(String(100), nullable=False, index=True)
    host = Column(String(255), nullable=False)
    port = Column(Integer, nullable=False, default=22)
    username = Column(String(100), nullable=False)
    authentication_type = Column(String(20), nullable=False, default="password")
    encrypted_password = Column(Text, nullable=True)
    encrypted_private_key = Column(Text, nullable=True)
    operating_system = Column(String(50), nullable=True, default="linux")
    environment = Column(String(20), nullable=False, default="production")
    description = Column(Text, nullable=True)
    status = Column(String(20), nullable=False, default="active")
    health_status = Column(String(30), nullable=False, default="unknown")
    connection_latency_ms = Column(Integer, nullable=True)
    last_seen = Column(DateTime, nullable=True)
    last_connected = Column(DateTime, nullable=True)
    last_health_check = Column(DateTime, nullable=True)
    last_successful_collection = Column(DateTime, nullable=True)
    health_error_message = Column(Text, nullable=True)
    consecutive_failures = Column(Integer, nullable=False, default=0)
    owner_id = Column(String(36), nullable=True, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    created_by = Column(String(36), nullable=True, index=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class CloudSource(Base):
    """Account-owned cloud telemetry source (CLOUD environment only). The client secret is stored encrypted."""
    __tablename__ = "cloud_sources"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    provider = Column(String(30), nullable=False, default="AZURE", index=True)
    source_type = Column(String(40), nullable=False, default="AZURE_LOG_ANALYTICS")
    tenant_id = Column(String(255), nullable=False)
    client_id = Column(String(64), nullable=False)
    encrypted_client_secret = Column(Text, nullable=False)
    workspace_id = Column(String(64), nullable=False, index=True)
    connection_status = Column(String(20), nullable=False, default="UNTESTED")
    last_connection_test = Column(DateTime, nullable=True)
    connection_error_code = Column(String(40), nullable=True)
    connection_error = Column(Text, nullable=True)
    last_collection_at = Column(DateTime, nullable=True)
    last_collection_status = Column(String(30), nullable=True)
    last_collection_error = Column(Text, nullable=True)
    last_successful_collection = Column(DateTime, nullable=True)
    owner_id = Column(String(36), nullable=True, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    created_by = Column(String(36), nullable=True, index=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class CloudCollectionRun(Base):
    """One collection attempt against a CloudSource. Counts and safe error codes only, never credentials."""
    __tablename__ = "cloud_collection_runs"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    cloud_source_id = Column(String(36), nullable=False, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    requested_by = Column(String(36), nullable=True)
    # Same value as normalized_data.collection_id on the events this run stored.
    collection_id = Column(String(36), nullable=True, index=True)
    mode = Column(String(20), nullable=False, default="LOOKBACK")
    status = Column(String(20), nullable=False, default="RUNNING")
    started_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    window_start = Column(DateTime, nullable=False)
    window_end = Column(DateTime, nullable=False)
    completed_at = Column(DateTime, nullable=True)
    max_records_per_source = Column(Integer, nullable=True)
    rows_retrieved = Column(Integer, nullable=False, default=0)
    rows_normalized = Column(Integer, nullable=False, default=0)
    rows_failed = Column(Integer, nullable=False, default=0)
    rows_stored = Column(Integer, nullable=False, default=0)
    rows_duplicate = Column(Integer, nullable=False, default=0)
    truncated = Column(Boolean, nullable=False, default=False)
    error_code = Column(String(40), nullable=True)
    error_message = Column(Text, nullable=True)
    # JSON list: per Azure source status, row counts, truncation and resume point.
    source_results = Column(Text, nullable=True)


class CollectionRun(Base):
    """Record of a log collection execution against a server."""
    __tablename__ = "collection_runs"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    server_id = Column(String(36), nullable=False, index=True)
    status = Column(String(20), nullable=False, default="running")
    processed = Column(Integer, nullable=False, default=0)
    inserted = Column(Integer, nullable=False, default=0)
    duplicates = Column(Integer, nullable=False, default=0)
    failed = Column(Integer, nullable=False, default=0)
    skipped = Column(Integer, nullable=False, default=0)
    duration_ms = Column(Integer, nullable=True)
    error_message = Column(Text, nullable=True)
    started_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    completed_at = Column(DateTime, nullable=True)


class LinuxCollectionState(Base):
    """Per-server incremental collection position. One row per Linux server, never shared."""
    __tablename__ = "linux_collection_state"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    server_id = Column(String(36), nullable=False, unique=True, index=True)
    # Cursor and realtime of the last journal entry whose batch was stored successfully.
    journal_cursor = Column(Text, nullable=True)
    journal_boot_id = Column(String(64), nullable=True)
    journal_realtime_usec = Column(BigInteger, nullable=True)
    journal_current_boot_id = Column(String(64), nullable=True)
    journal_persistent = Column(Boolean, nullable=True)
    journal_storage = Column(String(32), nullable=True)
    journal_boots_available = Column(Integer, nullable=True)
    last_mode = Column(String(16), nullable=True)
    last_entries_read = Column(Integer, nullable=True)
    backlog_pending = Column(Boolean, nullable=False, default=False)
    last_reboot_detected_at = Column(DateTime, nullable=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class PresentationTriggerState(Base):
    """Progress of the presentation demo trigger for one tenant scope and environment."""
    __tablename__ = "presentation_trigger_state"
    __table_args__ = (
        UniqueConstraint("scope_key", "environment", name="uq_presentation_trigger_scope_environment"),
    )

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    # "account:<id>" or "owner:<id>", the same tenant scope the presentation records use.
    scope_key = Column(String(80), nullable=False, index=True)
    environment = Column(String(20), nullable=False)
    owner_id = Column(String(36), nullable=True, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    # Successful manual collections required for the next trigger (1-3), and how many have counted so far.
    trigger_interval = Column(Integer, nullable=False)
    progress = Column(Integer, nullable=False, default=0)
    last_counted_run_id = Column(String(36), nullable=True)
    last_triggered_run_id = Column(String(36), nullable=True)
    last_triggered_at = Column(DateTime, nullable=True)
    triggers_generated = Column(Integer, nullable=False, default=0)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class CollectionN8nSequence(Base):
    """Durable successful-collection counter per tenant scope and source family (LINUX or CLOUD)."""
    __tablename__ = "collection_n8n_sequences"
    __table_args__ = (
        UniqueConstraint("scope_key", "source_type", name="uq_collection_n8n_sequence_scope_source"),
    )

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    scope_key = Column(String(80), nullable=False, index=True)
    source_type = Column(String(20), nullable=False)
    owner_id = Column(String(36), nullable=True, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    success_count = Column(Integer, nullable=False, default=0)
    last_counted_run_id = Column(String(36), nullable=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class CollectionN8nDispatch(Base):
    """Idempotent outbox for alternate-success collection webhooks to n8n (one row per qualifying run)."""
    __tablename__ = "collection_n8n_dispatches"
    __table_args__ = (
        UniqueConstraint("event_id", name="uq_collection_n8n_dispatch_event_id"),
        UniqueConstraint("source_type", "collection_run_id", name="uq_collection_n8n_dispatch_run"),
    )

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    event_id = Column(String(36), nullable=False, index=True)
    source_type = Column(String(20), nullable=False, index=True)
    collection_run_id = Column(String(36), nullable=False, index=True)
    scope_key = Column(String(80), nullable=False, index=True)
    owner_id = Column(String(36), nullable=True, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    sequence_number = Column(Integer, nullable=False)
    outcome = Column(String(32), nullable=False)
    collection_completed_at = Column(DateTime, nullable=True)
    # PENDING → SENT | FAILED. Collection success is independent of this status.
    status = Column(String(20), nullable=False, default="PENDING", index=True)
    attempt_count = Column(Integer, nullable=False, default=0)
    last_attempt_at = Column(DateTime, nullable=True)
    sent_at = Column(DateTime, nullable=True)
    last_http_status = Column(Integer, nullable=True)
    last_error = Column(String(240), nullable=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class Event(Base):
    """Database model for normalized security logs."""
    __tablename__ = "events"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    event_id = Column(String(36), unique=True, nullable=False, index=True)
    server_id = Column(String(36), nullable=True, index=True)
    owner_id = Column(String(36), nullable=True, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    data_scope = Column(String(20), nullable=False, default=DATA_SCOPE_PRIVATE, index=True)
    timestamp = Column(DateTime, nullable=False, index=True)
    collection_timestamp = Column(DateTime, nullable=True, index=True)
    timestamp_source = Column(String(40), nullable=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    hostname = Column(String(100), nullable=False)
    username = Column(String(100), nullable=True)
    source_ip = Column(String(45), nullable=True, index=True)
    event_type = Column(String(50), nullable=False, index=True)
    category = Column(String(50), nullable=False)
    severity = Column(String(20), nullable=False, index=True)
    risk_score = Column(Integer, nullable=False, index=True)
    risk_level = Column(String(20), nullable=True, index=True)
    command = Column(Text, nullable=True)
    process = Column(String(50), nullable=True)
    message = Column(Text, nullable=False)
    raw_log = Column(Text, nullable=False)
    normalized_data = Column(Text, nullable=True)
    hash = Column(String(64), unique=True, nullable=False, index=True)
    cpu_usage = Column(Float, nullable=True)
    memory_usage = Column(Float, nullable=True)
    disk_usage = Column(Float, nullable=True)
    login_time = Column(DateTime, nullable=True)
    logout_time = Column(DateTime, nullable=True)
    failed_login_count = Column(Integer, nullable=True)
    session_duration = Column(Float, nullable=True)
    commands_executed = Column(Integer, nullable=True)
    network_connections = Column(Integer, nullable=True)
    source_type = Column(String(20), nullable=False, default="LINUX", index=True)
    provider = Column(String(30), nullable=True, index=True)
    data_origin = Column(String(30), nullable=False, default="LIVE_LINUX", index=True)
    dataset_name = Column(String(80), nullable=True, index=True)
    is_labelled = Column(Boolean, nullable=False, default=False)
    original_label = Column(String(30), nullable=True, index=True)
    actor_id = Column(String(255), nullable=True)
    resource_id = Column(String(255), nullable=True)
    resource_type = Column(String(80), nullable=True)
    operation = Column(Text, nullable=True)
    parser_status = Column(String(20), nullable=False, default="PARSED", index=True)
    session_id = Column(String(120), nullable=True, index=True)
    typing_speed_cpm = Column(Float, nullable=True)
    command_rate_per_minute = Column(Float, nullable=True)
    command_error_rate = Column(Float, nullable=True)
    idle_time_seconds = Column(Float, nullable=True)
    repeated_command_ratio = Column(Float, nullable=True)
    session_duration_minutes = Column(Float, nullable=True)
    login_hour = Column(Integer, nullable=True)
    behavioral_risk_score = Column(Integer, nullable=True, index=True)
    behavioral_classification = Column(String(40), nullable=True, index=True)
    risk_reasons = Column(Text, nullable=True)
    baseline_version = Column(Integer, nullable=True)


class DatasetImport(Base):
    """Track bounded public dataset import runs."""
    __tablename__ = "dataset_imports"
    __table_args__ = (
        UniqueConstraint("owner_id", "dataset_name", "source_file_hash", name="uq_dataset_import_owner_file"),
    )

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    owner_id = Column(String(36), nullable=False, index=True)
    dataset_name = Column(String(80), nullable=False, index=True)
    dataset_version = Column(String(80), nullable=True)
    source_file = Column(String(500), nullable=False)
    source_file_hash = Column(String(64), nullable=False, index=True)
    status = Column(String(20), nullable=False, default="PENDING", index=True)
    total_records_discovered = Column(Integer, nullable=False, default=0)
    records_processed = Column(Integer, nullable=False, default=0)
    records_imported = Column(Integer, nullable=False, default=0)
    records_skipped = Column(Integer, nullable=False, default=0)
    records_failed = Column(Integer, nullable=False, default=0)
    batch_size = Column(Integer, nullable=False, default=500)
    import_limit = Column(Integer, nullable=True)
    started_at = Column(DateTime, nullable=True)
    completed_at = Column(DateTime, nullable=True)
    error_message = Column(Text, nullable=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class BehaviorProfile(Base):
    """Per-user aggregate behavioral baseline; never stores keystroke content."""
    __tablename__ = "behavior_profiles"
    __table_args__ = (
        UniqueConstraint("owner_id", "identity_key", "server_id", name="uq_behavior_profile_owner_identity_server"),
    )

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    owner_id = Column(String(36), nullable=False, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    identity_key = Column(String(255), nullable=False, index=True)
    user_id = Column(String(255), nullable=True, index=True)
    linux_username = Column(String(255), nullable=True)
    server_id = Column(String(36), nullable=True, index=True)
    average_typing_speed = Column(Float, nullable=True)
    std_typing_speed = Column(Float, nullable=True)
    average_command_rate = Column(Float, nullable=True)
    std_command_rate = Column(Float, nullable=True)
    average_command_error_rate = Column(Float, nullable=True)
    std_command_error_rate = Column(Float, nullable=True)
    average_idle_time = Column(Float, nullable=True)
    std_idle_time = Column(Float, nullable=True)
    average_repeated_command_ratio = Column(Float, nullable=True)
    std_repeated_command_ratio = Column(Float, nullable=True)
    average_session_duration = Column(Float, nullable=True)
    std_session_duration = Column(Float, nullable=True)
    usual_login_start = Column(Integer, nullable=True)
    usual_login_end = Column(Integer, nullable=True)
    profile_sample_count = Column(Integer, nullable=False, default=0)
    baseline_version = Column(Integer, nullable=False, default=0)
    status = Column(String(30), nullable=False, default="INSUFFICIENT_DATA", index=True)
    last_updated = Column(DateTime, nullable=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))
    updated_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class Alert(Base):
    """Security alert raised from rule-based or ML detection."""
    __tablename__ = "alerts"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    event_id = Column(String(36), unique=True, nullable=False, index=True)
    server_id = Column(String(36), nullable=True, index=True)
    owner_id = Column(String(36), nullable=True, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    title = Column(String(200), nullable=False)
    message = Column(Text, nullable=False)
    severity = Column(String(20), nullable=False, index=True)
    risk_score = Column(Integer, nullable=False)
    risk_level = Column(String(20), nullable=True)
    detection_type = Column(String(50), nullable=False, default="rule_based")
    acknowledged = Column(Boolean, nullable=False, default=False)
    explanation = Column(Text, nullable=True)
    recommendation = Column(Text, nullable=True)
    risk_factors = Column(Text, nullable=True)
    incident_id = Column(String(36), nullable=True, index=True)
    event_timestamp = Column(DateTime, nullable=True)
    confidence = Column(Float, nullable=True)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class Detection(Base):
    """Stored ML prediction result for a security event."""
    __tablename__ = "detections"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    server_id = Column(String(36), nullable=False, index=True)
    owner_id = Column(String(36), nullable=True, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    event_id = Column(String(36), nullable=False, index=True)
    isolation_score = Column(Float, nullable=True)
    random_forest_label = Column(String(20), nullable=True)
    classification = Column(String(20), nullable=True)
    confidence = Column(Float, nullable=True)
    detection_type = Column(String(50), nullable=True)
    message = Column(Text, nullable=True)
    is_anomaly = Column(Boolean, nullable=False, default=False)
    risk_score = Column(Integer, nullable=False, default=0)
    created_at = Column(DateTime, nullable=False, default=lambda: datetime.now(timezone.utc))


class Incident(Base):
    """Persisted hybrid correlation incident."""
    __tablename__ = "incidents"

    id = Column(String(36), primary_key=True, default=lambda: str(uuid.uuid4()))
    owner_id = Column(String(36), nullable=True, index=True)
    account_id = Column(String(36), nullable=True, index=True)
    incident_id = Column(String(80), unique=True, nullable=False, index=True)
    title = Column(String(240), nullable=False)
    severity = Column(String(20), nullable=False, default="medium")
    risk_score = Column(Integer, nullable=False, default=0)
    confidence = Column(Integer, nullable=False, default=0)
    actor = Column(String(255), nullable=True, index=True)
